const dbResult = $input.first().json;

const fecha = new Date(dbResult.generated_at).toLocaleDateString('es-ES');

const totalIncidentes = Number(dbResult.total_incidents || 0);
const totalAlertas = Number(dbResult.total_alerts || 0);
const totalConsultas = Number(dbResult.total_legal_queries || 0);

const incidentsByType = dbResult.incidents_by_type || [];
const alertsSummary = dbResult.alerts_summary || {};
const topLocations = dbResult.top_locations || [];

// Totales separados para Sheets / Looker Studio
const getTotalByType = (type) => {
  const found = incidentsByType.find(i => i.incident_type === type);
  return Number(found?.total || 0);
};

const incendiosTotal = getTotalByType('INCENDIO');
const plagasTotal = getTotalByType('PLAGA');
const permisosTotal = getTotalByType('PERMISO');
const incidenciasTotal = getTotalByType('INCIDENCIA');
const partesTrabajoTotal = getTotalByType('PARTE_TRABAJO');

const incidentesAlta = incidentsByType.reduce((sum, i) => sum + Number(i.alta || 0), 0);
const incidentesMedia = incidentsByType.reduce((sum, i) => sum + Number(i.media || 0), 0);
const incidentesBaja = incidentsByType.reduce((sum, i) => sum + Number(i.baja || 0), 0);

const topUbicacionesTexto = topLocations.length
  ? topLocations.map(loc => `${loc.location}: ${loc.incidents}`).join(' | ')
  : 'Sin datos';

// Mensaje resumen
let summaryMessage = `🌲 *AI FOREST ASSISTANT - RESUMEN SEMANAL*

📅 *Periodo:* Últimos 7 días
📊 *Generado:* ${fecha}

━━━━━━━━━━━━━━━━━━━━
📌 *ESTADÍSTICAS GENERALES*
━━━━━━━━━━━━━━━━━━━━
🔥 Incidentes registrados: *${totalIncidentes}*
🚨 Incidentes alta prioridad: *${incidentesAlta}*
⚠️ Alertas enviadas: *${totalAlertas}*
📋 Consultas legales: *${totalConsultas}*

━━━━━━━━━━━━━━━━━━━━
📌 *INCIDENTES POR TIPO*
━━━━━━━━━━━━━━━━━━━━`;

if (incidentsByType.length > 0) {
  incidentsByType.forEach(i => {
    summaryMessage += `\n• ${i.incident_type}: ${i.total} (${i.alta || 0} ALTA, ${i.media || 0} MEDIA, ${i.baja || 0} BAJA)`;
  });
} else {
  summaryMessage += `\nSin incidentes registrados.`;
}

summaryMessage += `

━━━━━━━━━━━━━━━━━━━━
📌 *ALERTAS POR RIESGO*
━━━━━━━━━━━━━━━━━━━━
🔴 EXTREMO: ${alertsSummary.extremo || 0}
🟠 ALTO: ${alertsSummary.alto || 0}
🟡 MODERADO: ${alertsSummary.moderado || 0}
🟢 BAJO: ${alertsSummary.bajo || 0}`;

summaryMessage += `

━━━━━━━━━━━━━━━━━━━━
📍 *UBICACIONES CON MÁS INCIDENTES*
━━━━━━━━━━━━━━━━━━━━`;

if (topLocations.length > 0) {
  topLocations.forEach(loc => {
    summaryMessage += `\n• ${loc.location}: ${loc.incidents} incidentes`;
  });
} else {
  summaryMessage += `\nSin datos.`;
}

summaryMessage += `

━━━━━━━━━━━━━━━━━━━━
🌲 *Gracias por proteger nuestros bosques*
━━━━━━━━━━━━━━━━━━━━`;

// Registro histórico para Google Sheets
const historicalRecord = {
  metric_date: new Date().toISOString().split('T')[0],

  total_incidents: totalIncidentes,
  total_alerts: totalAlertas,
  total_legal_queries: totalConsultas,

  incidentes_alta: incidentesAlta,
  incidentes_media: incidentesMedia,
  incidentes_baja: incidentesBaja,

  incendios_total: incendiosTotal,
  plagas_total: plagasTotal,
  permisos_total: permisosTotal,
  incidencias_total: incidenciasTotal,
  partes_trabajo_total: partesTrabajoTotal,

  incidents_by_type: incidentsByType,
  alerts_summary: alertsSummary,
  top_locations: topLocations,
  top_locations_text: topUbicacionesTexto,

  metadata: {
    generated_at: dbResult.generated_at,
    period_days: 7
  }
};

return [{
  json: {
    ...dbResult,
    summary_message: summaryMessage,
    whatsapp_summary: summaryMessage,
    historical_record: historicalRecord
  }
}];

